        "items": [
          {
            "id": "comp-16",
            "title": "Relationnel",
            "badge": {
              "text": "Humaine",
              "className": "date-badge humaine"
            },
            "contentHtml": "<p class=\"formation-objective-text\">\n                                Grâce à mon <strong>bon relationnel</strong>, je m'intègre facilement dans un groupe tout en\n                                sachant travailler de manière <strong>autonome</strong>. Cela me permet de mener à bien nos\n                                <strong>projets collectifs</strong> en communiquant clairement et en coordonnant la\n                                <strong>répartition des tâches</strong> de manière intelligente.\n                                <br><br>\n                                <strong>Acquisition :</strong>\n                                <br><br>\n                                Mon <strong>sens du relationnel</strong> s'est développé à travers mes expériences\n                                professionnelles en caisse, qui m'ont confronté quotidiennement au <strong>contact\n                                    client</strong>, ainsi qu'à travers les cours de <strong>communication</strong> suivis\n                                en BUT R&amp;T. Ces enseignements m'ont appris à <strong>structurer mes idées</strong> et à les\n                                transmettre de manière claire, méthodique et <strong>adaptée à chaque\n                                    interlocuteur</strong>.\n                            </p>"
          },
          {
            "id": "comp-17",
            "title": "Curiosité",
            "badge": {
              "text": "Humaine",
              "className": "date-badge humaine"
            },
            "contentHtml": "<p class=\"formation-objective-text\">\n                                Naturellement <strong>curieux</strong>, je cherche toujours à <strong>approfondir mes\n                                    connaissances</strong>, ce qui me permet de progresser et d'<strong>évoluer en\n                                    permanence</strong> dans mon domaine. Loin d'être un signe de lassitude, cette démarche\n                                traduit ma volonté constante de <strong>me perfectionner</strong>.\n                                <br><br>\n                                <strong>Acquisition :</strong>\n                                <br><br>\n                                Ma <strong>curiosité</strong> s'exprime avant tout à travers ma pratique artistique, où\n                                j'explore en permanence de nouveaux univers sans me limiter à une seule technique passant\n                                de l'<strong>aquarelle</strong> et la peinture traditionnelle au <strong>dessin\n                                    réaliste</strong> ou au <strong>pixel art</strong>, tout en restant ouvert à d'autres\n                                médiums. Cet esprit d'exploration se retrouve également dans le domaine informatique, où\n                                l'interconnexion des <strong>langages de programmation</strong> et des technologies m'incite\n                                à ne jamais me cantonner à un seul sujet et à <strong>renouveler sans cesse mes\n                                    apprentissages</strong>.\n                            </p>"
          },
          {
            "id": "comp-18",
            "title": "Rigueur",
            "badge": {
              "text": "Humaine",
              "className": "date-badge humaine"
            },
            "contentHtml": "<p class=\"formation-objective-text\">\n                                Soucieux de la <strong>qualité de mon travail</strong>, je m'attache à livrer des\n                                <strong>résultats soignés</strong>. J'applique cette même <strong>rigueur</strong> lors des\n                                phases de mise en place, en <strong>sécurisant chaque procédure</strong> pour écarter tout\n                                risque de dysfonctionnement.\n                                <br><br>\n                                <strong>Acquisition :</strong>\n                                <br><br>\n                                Ma <strong>rigueur</strong> s'est développée à travers les nombreux travaux pratiques en\n                                réseaux réalisés durant mon BUT R&amp;T, où le <strong>paramétrage des équipements</strong>\n                                exige un contrôle minutieux : la moindre erreur de configuration peut bloquer l'ensemble\n                                d'un réseau. Cette exigence s'est également renforcée lors de mes expériences\n                                professionnelles en mise en rayon, où le <strong>respect strict des normes</strong> et le\n                                soin apporté à la disposition des produits étaient essentiels pour garantir un <strong>rayon\n                                    irréprochable</strong>.\n                            </p>"
          }
        ]
